import inspect
from filelock import FileLock

class FilePathLock(FileLock):
    def __init__(self, file_path, timeout=-1, **kwargs):
        super().__init__(file_path + ".lock", timeout=timeout, **kwargs)

sig = inspect.signature(FilePathLock.__init__)
print(sig.parameters)
for p in sig.parameters.values():
    print(p.name, p.kind)

